const body = $json.body || $json;

// Formato esperado desde Voiceflow:
// {
//   "intent": "faq|order_status|escalation",
//   "query": "cuanto tarda el envio",
//   "customer_name": "Maria",
//   "customer_email": "maria@email.com",
//   "order_id": "PED-001",
//   "channel": "Web"
// }

const intent = body.intent || 'faq';
const query = (body.query || '').toLowerCase();
const customerName = body.customer_name || 'Cliente';
const customerEmail = body.customer_email || '';
const orderId = body.order_id || '';
const channel = body.channel || 'Web';

return [{
  json: {
    intent: intent,
    query: query,
    customerName: customerName,
    customerEmail: customerEmail,
    orderId: orderId,
    channel: channel,
    needsEscalation: false
  }
}];

const orders = $json.results || $json.data || [];
const req = $('Procesar Consulta').first().json;

if (orders.length === 0) {
  return [{
    json: {
      response: 'No he encontrado ningun pedido con ese numero y email. Verifica que los datos son correctos. Si necesitas ayuda, puedo ponerte en contacto con una persona.',
      action: 'respond',
      needsEscalation: false
    }
  }];
}

const order = orders[0];
const props = order.properties || {};
const estado = props['Estado pedido']?.select?.name || 'desconocido';
const fecha = props['date:Fecha:start'] || '';
const total = props['Importe total']?.number || 0;
const articulos = props['Artículos']?.rich_text?.[0]?.plain_text || '';

return [{
  json: {
    response: `Tu pedido ${req.orderId} esta en estado: ${estado}.` + (fecha ? ` Fecha: ${fecha}.` : '') + (total ? ` Importe: ${total} euros.` : '') + (articulos ? ` Articulos: ${articulos}.` : '') + ` Si tienes mas dudas, no dudes en preguntar.`,
    action: 'respond',
    needsEscalation: false
  }
}];

return [{
  json: {
    response: 'Para consultar el estado de tu pedido necesito tu numero de pedido y el email con el que lo realizaste. Por ejemplo: numero PED-001 y email maria@email.com.',
    action: 'respond',
    needsEscalation: false
  }
}];

const faqs = $json.results || $json.data || [];
const query = $('Procesar Consulta').first().json.query;

if (faqs.length === 0) {
  return [{
    json: {
      response: 'Lo siento, no tengo informacion sobre eso en este momento. Te puedo poner en contacto con una persona si lo prefieres.',
      action: 'respond',
      needsEscalation: true,
      faqMatch: false
    }
  }];
}

// Buscar la FAQ que mejor coincida por palabras clave
let bestMatch = null;
let bestScore = 0;

for (const faq of faqs) {
  const props = faq.properties || {};
  const question = (props.Pregunta?.title?.[0]?.plain_text || '').toLowerCase();
  const keywords = (props['Palabras clave']?.rich_text?.[0]?.plain_text || '').toLowerCase().split(',').map(k => k.trim());
  const respuestaCorta = props['Respuesta corta']?.rich_text?.[0]?.plain_text || '';
  const respuestaCompleta = props['Respuesta completa']?.rich_text?.[0]?.plain_text || '';
  const escalarHumano = props['Escalar a humano'] === '__YES__';

  let score = 0;
  // Coincidencia por pregunta
  if (query.includes(question) || question.includes(query)) score += 5;
  // Coincidencia por palabras clave
  for (const kw of keywords) {
    if (kw && query.includes(kw)) score += 3;
  }
  // Coincidencia por palabras en la pregunta
  const queryWords = query.split(' ').filter(w => w.length > 2);
  for (const w of queryWords) {
    if (question.includes(w)) score += 1;
  }

  if (score > bestScore) {
    bestScore = score;
    bestMatch = {
      question: props.Pregunta?.title?.[0]?.plain_text || '',
      respuestaCorta: respuestaCorta,
      respuestaCompleta: respuestaCompleta,
      escalarHumano: escalarHumano,
      pageId: faq.id
    };
  }
}

if (bestMatch && bestScore > 0) {
  const needsEscalation = bestMatch.escalarHumano;
  let response = bestMatch.respuestaCompleta || bestMatch.respuestaCorta;

  if (needsEscalation) {
    response += '\n\nSi necesitas mas detalles, puedo ponerte en contacto con una persona que te ayudara.';
  }

  return [{
    json: {
      response: response,
      action: 'respond',
      needsEscalation: needsEscalation,
      faqMatch: true,
      faqQuestion: bestMatch.question
    }
  }];
}

// Sin coincidencia
return [{
  json: {
    response: 'No estoy seguro de haber entendido tu consulta. Puedo ayudarte con: envios, devoluciones, reservas, estado de libros, pagos, compra de libros o consultar tu pedido. Si prefieres, puedo ponerte en contacto con una persona.',
    action: 'respond',
    needsEscalation: true,
    faqMatch: false
  }
}];

